// ---------- language ----------
function getLang(){ return localStorage.getItem('fh_lang') || 'en'; }
function setLang(lang){ localStorage.setItem('fh_lang', lang); applyI18n(); }

function t(key, vars){
  const lang = getLang();
  let str = (I18N[lang] && I18N[lang][key]) || I18N.en[key] || key;
  if(vars){
    Object.keys(vars).forEach(k => { str = str.split('{'+k+'}').join(vars[k]); });
  }
  return str;
}

function applyI18n(){
  const lang = getLang();
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    let vars = null;
    const varsAttr = el.getAttribute('data-i18n-vars');
    if(varsAttr){ try{ vars = JSON.parse(varsAttr); }catch(e){} }
    const val = t(key, vars);
    if(val) el.innerHTML = val;
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    const val = t(key);
    if(val) el.setAttribute('placeholder', val);
  });
  document.querySelectorAll('.lang-select').forEach(sel => { sel.value = lang; });
  document.documentElement.setAttribute('lang', lang);
}

// ---------- currency ----------
const CURRENCIES = ['USD','EUR','GBP','ARS','BRL','MXN','JPY','CNY'];
const CURRENCY_SYMBOL = { USD:'$', EUR:'€', GBP:'£', ARS:'AR$', BRL:'R$', MXN:'MX$', JPY:'¥', CNY:'¥' };
let FX_RATES = null; // base USD

async function loadFxRates(){
  if(FX_RATES) return FX_RATES;
  try{
    const res = await fetch('https://api.frankfurter.app/latest?from=USD');
    const data = await res.json();
    FX_RATES = { USD:1, ...data.rates };
  }catch(e){
    FX_RATES = { USD:1, EUR:0.92, GBP:0.79, ARS:1000, BRL:5.5, MXN:18, JPY:150, CNY:7.2 }; // rough fallback if the FX API is unreachable
  }
  return FX_RATES;
}

function getDisplayCurrency(){ return localStorage.getItem('fh_currency') || 'USD'; }
function setDisplayCurrency(c){ localStorage.setItem('fh_currency', c); }

// convert an amount stored in `fromCurrency` into the user's selected display currency
async function convertPrice(amount, fromCurrency){
  const rates = await loadFxRates();
  const display = getDisplayCurrency();
  if(fromCurrency === display) return { amount, currency: display };
  const usdAmount = amount / (rates[fromCurrency] || 1);
  const converted = usdAmount * (rates[display] || 1);
  return { amount: Math.round(converted), currency: display };
}

function formatMoney(amount, currency){
  return `${CURRENCY_SYMBOL[currency] || currency + ' '}${amount}`;
}
